<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useToast} from 'vue-toastification';import {useAuthStore} from '@/stores/auth';import api from '@/services/api'
const route=useRoute(),router=useRouter(),toast=useToast(),auth=useAuthStore(),m=ref<any>(null),loading=ref(true);const canEdit=computed(()=>m.value&&['DRAFT','REVISI_PEMERIKSA','REVISI_PENANDATANGAN'].includes(m.value.status));const canSignSigner=computed(()=>m.value?.status==='MENUNGGU_PENANDATANGAN'&&m.value?.signer_id===auth.user?.id&&!m.value?.signed_at);const canSignNotulis=computed(()=>m.value?.status==='MENUNGGU_PENANDATANGAN'&&m.value?.notulis_id===auth.user?.id&&!m.value?.notulis_signed_at);const labels:any={DRAFT:'Draft',MENUNGGU_PEMERIKSA:'Menunggu Pemeriksa',MENUNGGU_PENANDATANGAN:'Menunggu TTD',REVISI_PEMERIKSA:'Revisi',REVISI_PENANDATANGAN:'Revisi',DITANDATANGANI:'Ditandatangani'}
onMounted(async()=>{try{m.value=(await api.get(`/meeting-minutes/${route.params.id}`)).data}catch{}finally{loading.value=false}})
async function act(path:string){try{await api.post(`/meeting-minutes/${m.value.id}/${path}`,{action:'approve'});m.value=(await api.get(`/meeting-minutes/${m.value.id}`)).data;toast.success('Tanda tangan/status berhasil dicatat')}catch(e:any){toast.error(e?.response?.data?.message??'Gagal')}}
async function download(){const r=await api.get(`/meeting-minutes/${m.value.id}/pdf`,{responseType:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(r.data);a.download='notulen.pdf';a.click()}
async function share(){try{await api.post(`/meeting-minutes/${m.value.id}/share`);toast.success('Notulen dibagikan kepada peserta rapat.')}catch(e:any){toast.error(e?.response?.data?.message??'Gagal membagikan notulen.')}}
</script>
<template><div v-if="loading" class="p-10 text-center">Memuat...</div><div v-else-if="m" class="max-w-4xl space-y-5"><div class="flex justify-between"><div><h1 class="text-xl font-bold">{{m.title}}</h1><p class="text-sm text-gray-500">{{m.number||'Draft'}} · {{labels[m.status]}}</p></div><div class="flex gap-2"><button v-if="canEdit" class="px-3 py-2 bg-amber-100 rounded" @click="router.push(`/agenda/notulen/${m.id}/edit`)">Edit</button><button class="px-3 py-2 bg-gray-100 rounded" @click="download">Download PDF</button><button v-if="m.status==='DITANDATANGANI'" class="px-3 py-2 bg-blue-600 text-white rounded" @click="share">Kirim ke Peserta</button><button v-if="m.status==='MENUNGGU_PEMERIKSA'" class="px-3 py-2 bg-blue-600 text-white rounded" @click="act('review')">Setujui</button><button v-if="canSignSigner" class="px-3 py-2 bg-green-600 text-white rounded" @click="act('sign')">Tanda Tangani sebagai Penandatangan</button><button v-if="canSignNotulis" class="px-3 py-2 bg-indigo-600 text-white rounded" @click="act('sign')">Tanda Tangani sebagai Notulis</button></div></div><div class="bg-white border rounded-xl p-6 space-y-5"><p><b>Tanggal:</b> {{m.meeting_date}} · <b>Tempat:</b> {{m.location||'-'}}</p><section v-for="field in [['identity','Identitas'],['agenda','Agenda'],['proceedings','Jalannya Rapat'],['decisions','Keputusan'],['closing','Penutup']]" :key="field[0]"><h2 class="font-semibold border-b pb-1">{{field[1]}}</h2><p class="whitespace-pre-line text-sm mt-2">{{m[field[0]]||'-'}}</p></section><section><h2 class="font-semibold border-b pb-1">Peserta</h2><ul class="text-sm list-disc ml-5"><li v-for="p in m.participants">{{p.name||p}} <span v-if="p.position">— {{p.position}}</span></li></ul></section></div></div></template>
